root=ET.fromstring(driver.page_source)
nav=[]
for e in root.iter():
 a=e.attrib
 if a.get('bounds','').endswith('[1080,2337]') or (a.get('content-desc') in ('Video','Audio','Browse','Playlists','More')):
  nav.append({k:a.get(k) for k in ('class','text','content-desc','resource-id','clickable','selected','bounds') if a.get(k)})
{'nav':nav[-25:]}

