driver.drag_and_drop(moves[3],moves[2])
import time; time.sleep(.8)
root=ET.fromstring(driver.page_source)
tracks=[e.attrib.get('text') for e in root.iter() if e.attrib.get('resource-id')=='org.videolan.vlc:id/title' and e.attrib.get('text')]
{'tracks':tracks}

from selenium.webdriver.common.action_chains import ActionChains
pkg=driver.current_package
moves=[m for m in driver.find_elements(AppiumBy.ID,'org.videolan.vlc:id/item_move') if m.is_displayed()]
if len(moves)!=4: raise RuntimeError(len(moves))
ActionChains(driver).click_and_hold(moves[3]).move_to_element(moves[2]).release().perform()
import time; time.sleep(.8)
root=ET.fromstring(driver.page_source)
tracks=[e.attrib.get('text') for e in root.iter() if e.attrib.get('resource-id')=='org.videolan.vlc:id/title' and e.attrib.get('text')]
